using UnityEngine;
using UnityEngine.Rendering;
namespace Alterverse.Visuals
{
public sealed class TowerVisualShell:MonoBehaviour
{
private int team;private Transform visualRoot;private Material darkMat,midMat,energyMat;
public void Configure(int value){team=value;Build();}
private void Build(){if(visualRoot!=null)return;Renderer original=GetComponent<Renderer>();if(original!=null)original.enabled=false;visualRoot=new GameObject("DF_TowerVisual").transform;visualRoot.SetParent(transform,false);Color dark=team==0?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;Color mid=team==0?StylizedArtDirection.ZeroMid:StylizedArtDirection.LumenMid;Color energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;darkMat=CreateMaterial("TowerDark",dark,.48f,.34f,false);midMat=CreateMaterial("TowerMid",mid,.58f,.46f,false);energyMat=CreateMaterial("TowerEnergy",energy,.12f,.72f,true);if(team==0)BuildZero();else BuildLumen();}
private void BuildZero(){Create("BrokenSpine",PrimitiveType.Cube,new Vector3(0,0,0),new Vector3(.62f,1.7f,.62f),darkMat,new Vector3(0,18,11));for(int i=0;i<3;i++){float a=(i*120+25)*Mathf.Deg2Rad;Create("FractureArm",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.62f,.35f+i*.22f,Mathf.Sin(a)*.62f),new Vector3(.18f,.75f,.32f),midMat,new Vector3(15+i*8,-i*37,32));}Create("RiftEye",PrimitiveType.Cube,new Vector3(0,.78f,.36f),new Vector3(.22f,.42f,.08f),energyMat,new Vector3(0,0,45),true);Create("SplitCrownL",PrimitiveType.Cube,new Vector3(-.32f,1.12f,0),new Vector3(.14f,.72f,.22f),midMat,new Vector3(0,0,-24));Create("SplitCrownR",PrimitiveType.Cube,new Vector3(.34f,1.06f,.04f),new Vector3(.14f,.58f,.22f),energyMat,new Vector3(0,0,31),true);}
private void BuildLumen(){Create("CorePillar",PrimitiveType.Cube,new Vector3(0,0,0),new Vector3(.58f,1.65f,.58f),darkMat,new Vector3(0,45,0));for(int i=0;i<4;i++){float a=(45+i*90)*Mathf.Deg2Rad;Create("LightFin",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.54f,.35f,Mathf.Sin(a)*.54f),new Vector3(.12f,1.05f,.3f),midMat,new Vector3(0,-45-i*90,0));}Create("Lens",PrimitiveType.Cube,new Vector3(0,.78f,.42f),new Vector3(.3f,.3f,.08f),energyMat,new Vector3(0,0,45),true);Create("Crown",PrimitiveType.Cube,new Vector3(0,1.13f,0),new Vector3(.46f,.14f,.46f),energyMat,new Vector3(0,45,0),true);}
private GameObject Create(string name,PrimitiveType type,Vector3 pos,Vector3 scale,Material material,Vector3 rot,bool pulse=false){GameObject g=GameObject.CreatePrimitive(type);g.name="DF_"+name;g.transform.SetParent(visualRoot,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.transform.localRotation=Quaternion.Euler(rot);Collider c=g.GetComponent<Collider>();if(c!=null){c.enabled=false;Object.Destroy(c);}Renderer r=g.GetComponent<Renderer>();if(r!=null){r.sharedMaterial=material;r.receiveShadows=!pulse;if(pulse)r.shadowCastingMode=ShadowCastingMode.Off;}if(pulse)g.AddComponent<ArenaLightPulse>();return g;}
private static Material CreateMaterial(string name,Color color,float metallic,float smoothness,bool emissive){Shader shader=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");Material material=new(shader){name="DF_"+name};material.color=color;if(material.HasProperty("_BaseColor"))material.SetColor("_BaseColor",color);if(material.HasProperty("_Metallic"))material.SetFloat("_Metallic",metallic);if(material.HasProperty("_Smoothness"))material.SetFloat("_Smoothness",smoothness);if(emissive){material.EnableKeyword("_EMISSION");if(material.HasProperty("_EmissionColor"))material.SetColor("_EmissionColor",color*1.55f);}return material;}
private void OnDestroy(){if(darkMat!=null)Destroy(darkMat);if(midMat!=null)Destroy(midMat);if(energyMat!=null)Destroy(energyMat);}
}
}
